/* ---------- 照片堆叠层：主照片下面垫两张错位黑框 ---------- */
.cup-stack-layers { position: absolute; inset: 0; z-index: 5; pointer-events: none; }
.cup-under {
  position: absolute;
  left: 50%;
  top: 33%;
  width: min(84vw, 470px);
  height: 0;
  padding-bottom: 52%;     /* 与主照片近似的框体比例 */
  transform: translate(-50%, -50%);
  background: linear-gradient(180deg, #0a090f 0%, #14121c 55%, #08070c 100%);
  border: 2px solid #000;
  box-shadow: 0 10px 30px rgba(15, 8, 35, .45), inset 0 0 0 1px rgba(150, 140, 175, .18);
  opacity: 0;
}
.cup-under.u1 { transform: translate(-49.2%, -47%) rotate(2.2deg); }
.cup-under.u2 { transform: translate(-50.9%, -53%) rotate(-2.6deg); }
.cups-stage.done .cup-under { opacity: 1; }
.cups-stage.done .cup-under.u1 { animation: photo-in 1s cubic-bezier(.2, .9, .3, 1.12) .34s backwards; }
.cups-stage.done .cup-under.u2 { animation: photo-in 1s cubic-bezier(.2, .9, .3, 1.12) .46s backwards; }
/* 每翻一张，堆叠层微调角度，像真的在翻一摞照片 */
.cup-stack-layers[data-turn="1"] .u1 { transform: translate(-50.8%, -53%) rotate(-2.4deg); }
.cup-stack-layers[data-turn="1"] .u2 { transform: translate(-49.1%, -47%) rotate(2deg); }
.cup-stack-layers[data-turn="2"] .u1 { transform: translate(-50%, -50.5%) rotate(1.2deg); }
.cup-stack-layers[data-turn="2"] .u2 { transform: translate(-50%, -49.5%) rotate(-1.4deg); }

/* ---------- 右下角切换角标 ---------- */
.cup-photo-next {
  position: absolute;
  right: 10px;
  bottom: 8px;
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(200, 190, 235, .14);
  border: 1px solid rgba(180, 170, 215, .4);
  color: #cfcaf0;
  font-size: 16px;
  cursor: pointer;
  opacity: 0;
  pointer-events: none;
  transition: opacity .5s ease, background .2s ease, transform .2s ease;
  z-index: 3;
}
.cups-stage.done .cup-photo-next { opacity: .92; pointer-events: auto; }
.cup-photo-next:hover { background: rgba(200, 190, 235, .3); transform: scale(1.1); }
.cup-photo-next:active { transform: scale(.92); }

/* ---------- 照片切换动画：当前张快速翻走 ---------- */
.cup-photo.flipping { pointer-events: none; }
.cup-photo.flipping .cup-photo-img,
.cup-photo.flipping .cup-photo-text {
  animation: photo-flip .48s cubic-bezier(.4, 0, .3, 1);
}
@keyframes photo-flip {
  0%   { transform: translateX(0) rotate(0); opacity: 1; }
  45%  { transform: translateX(46%) rotate(3.5deg); opacity: 0; }
  55%  { transform: translateX(-46%) rotate(-3deg); opacity: 0; }
  100% { transform: translateX(0) rotate(0); opacity: 1; }
}

/* ================= 照片堆下方：中间的一句话（蓝色冷冬手写体） ================= */
.cup-gap-line {
  position: absolute;
  left: 50%;
  top: 0;                        /* 由 JS 按照片实际底部动态定位，换屏幕也不错位 */
  width: min(84vw, 450px);
  transform: translateX(-50%);
  text-align: center;
  font-family: 'MashanZheng Handwriting', "Kaiti SC", "STKaiti", "KaiTi", serif;
  font-size: clamp(17px, 4.6vw, 25px);
  line-height: 1.65;
  letter-spacing: .06em;
  white-space: pre-line;          /* 让 config 里的 \n 真的换行 */
  color: #b9d6f2;
  text-shadow:
    0 0 10px rgba(150, 195, 250, .5),
    0 0 26px rgba(120, 170, 235, .3),
    0 2px 5px rgba(6, 12, 26, .75);
  opacity: 0;
  transition: opacity 1.1s ease .5s;
  pointer-events: none;
  z-index: 6;
}
.cups-stage.done .cup-gap-line { opacity: 1; }

/* ================= 下方：老板专属自定义上传画布（黑框） ================= */
.cup-upload {
  position: absolute;
  left: 50%;
  top: 0;                        /* 同上：JS 排在句子下面 */
  width: min(56vw, 232px);
  height: min(30vw, 132px);
  transform: translate(-50%, 0);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background: linear-gradient(180deg, #0b0a10 0%, #13111b 60%, #08070c 100%);
  border: 2px solid #000;
  box-shadow:
    0 12px 30px rgba(15, 8, 35, .5),
    inset 0 0 0 1px rgba(150, 140, 175, .22);
  opacity: 0;
  transition: opacity 1.1s ease .8s;
  z-index: 7;
  cursor: pointer;
}
.cups-stage.done .cup-upload { opacity: 1; }

/* 空态：＋ 号 + 提示 */
.cup-upload .cu-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  color: #6d6a86;
  pointer-events: none;
}
.cup-upload .cu-plus { font-size: 26px; line-height: 1; opacity: .85; }
.cup-upload .cu-tip { font-size: 11px; letter-spacing: .22em; opacity: .7; }
.cup-upload.has-img .cu-empty { display: none; }

/* 已上传的照片 */
.cup-upload .cu-img {
  display: none;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.cup-upload.has-img .cu-img { display: block; }

/* 口令层：未解锁时点画布弹出 */
.cup-upload .cu-lock {
  position: absolute;
  inset: 0;
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px;
  background: rgba(8, 7, 12, .93);
}
.cup-upload.asking .cu-lock { display: flex; }
.cup-upload .cu-pass {
  width: 78%;
  padding: 7px 9px;
  text-align: center;
  color: #dfe6f5;
  background: rgba(255, 255, 255, .07);
  border: 1px solid rgba(160, 180, 220, .35);
  border-radius: 4px;
  font-size: 13px;
  letter-spacing: .2em;
  outline: none;
}
.cup-upload .cu-ok {
  padding: 5px 16px;
  color: #cfd9ee;
  background: rgba(120, 150, 210, .16);
  border: 1px solid rgba(160, 180, 220, .4);
  border-radius: 4px;
  font-size: 12px;
  letter-spacing: .16em;
  cursor: pointer;
}
.cup-upload .cu-ok:active { transform: scale(.95); }
.cup-upload.wrong { animation: cu-shake .38s ease; }
@keyframes cu-shake {
  0%,100% { transform: translate(-50%, 0); }
  25%     { transform: translate(calc(-50% - 7px), 0); }
  75%     { transform: translate(calc(-50% + 7px), 0); }
}

/* 移除按钮：解锁且有图时才出现 */
.cup-upload .cu-clear {
  position: absolute;
  top: 4px;
  right: 5px;
  width: 20px;
  height: 20px;
  display: none;
  align-items: center;
  justify-content: center;
  color: #cfd6e8;
  font-size: 12px;
  line-height: 1;
  background: rgba(20, 18, 28, .72);
  border-radius: 50%;
  z-index: 2;
}
.cup-upload.has-img .cu-clear { display: flex; }

/* ================= 上传画布明信片化：加大 + 米白纸 + 邮票/分隔线 ================= */
.cup-upload {
  width: min(86vw, 430px);
  height: min(57vw, 286px);
  padding: 12px;
  background:
    linear-gradient(150deg, rgba(255, 255, 255, .55), rgba(255, 255, 255, 0) 45%),
    linear-gradient(180deg, #efeeea 0%, #e7e5df 100%);
  border: none;
  border-radius: 5px;
  box-shadow:
    0 16px 36px rgba(24, 16, 44, .42),
    0 3px 8px rgba(24, 16, 44, .28),
    inset 0 0 0 1px rgba(118, 114, 138, .28);
}
/* 邮票框：右上角虚线小框 + 冷冬雪花 */
.cup-upload .cu-stamp {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 56px;
  height: 70px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1.5px dashed #b6b0a2;
  border-radius: 3px;
  background: rgba(255, 255, 255, .5);
  pointer-events: none;
}
.cup-upload .cu-stamp::after {
  content: '❄';
  font-size: 22px;
  color: #b9c4dd;
  text-shadow: 0 1px 2px rgba(90, 110, 160, .25);
}
/* 明信片中缝竖虚线 */
.cup-upload .cu-divider {
  position: absolute;
  top: 12px;
  bottom: 12px;
  left: 66%;
  border-left: 1.5px dashed #c8c3b5;
  pointer-events: none;
}
/* 照片区：白边内的左侧 66% */
.cup-upload .cu-empty {
  position: absolute;
  left: 12px;
  top: 12px;
  width: calc(66% - 12px);
  height: calc(100% - 24px);
  align-items: center;
  justify-content: center;
  color: #9b95a9;
  background: rgba(255, 255, 255, .34);
}
.cup-upload .cu-plus { color: #a49dbb; font-size: 30px; }
.cup-upload .cu-tip { color: #8f8aa0; }
.cup-upload .cu-img {
  position: absolute;
  left: 12px;
  top: 12px;
  width: calc(66% - 12px);
  height: calc(100% - 24px);
  object-fit: cover;
  box-shadow: 0 1px 5px rgba(30, 25, 50, .35);
}
/* 移除按钮：挪到照片区右上角（邮票框左侧） */
.cup-upload .cu-clear {
  right: auto;
  left: calc(66% - 26px);
  top: 16px;
  color: #f2f0f7;
  background: rgba(38, 33, 56, .68);
}
/* 口令层盖整张明信片 */
.cup-upload .cu-lock {
  background: rgba(14, 12, 20, .9);
}

/* ================= 上传框最终版：跟照片堆同款黑框；上传入口隐藏（连点5次） ================= */
.cup-upload {
  width: min(84vw, 470px);
  height: min(47vw, 238px);
  padding: 13px 13px 16px;
  background: linear-gradient(180deg, #0a090f 0%, #14121c 55%, #08070c 100%);
  border: 2px solid #000;
  border-radius: 0;
  box-shadow:
    0 16px 44px rgba(15, 8, 35, .55),
    inset 0 0 0 1px rgba(150, 140, 175, .28),
    0 0 30px rgba(190, 165, 255, .22);
}
/* 明信片装饰全部隐藏 */
.cup-upload .cu-stamp,
.cup-upload .cu-divider { display: none; }
/* 空态提示（＋上传照片）不显示：这是底层逻辑，照片走云端 */
.cup-upload .cu-empty { display: none; }
/* 照片铺满黑框内白边 */
.cup-upload .cu-img {
  left: 13px;
  top: 13px;
  width: calc(100% - 26px);
  height: calc(100% - 29px);
}
/* 移除按钮回右上角 */
.cup-upload .cu-clear {
  left: auto;
  right: 19px;
  top: 19px;
}

/* ================= 同步状态提示（默认不露，仅同步成功/失败时闪一下） ================= */
.cup-upload .cu-status {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 6px;
  text-align: center;
  font-size: 10px;
  letter-spacing: .08em;
  color: rgba(206, 198, 232, .8);
  text-shadow: 0 1px 5px rgba(0, 0, 0, .65);
  opacity: 0;
  transform: translateY(4px);
  transition: opacity .35s ease, transform .35s ease;
  pointer-events: none;
  z-index: 3;
}
.cup-upload.show-status .cu-status { opacity: 1; transform: translateY(0); }

/* ================= 画廊：老板编辑态（✕ 角标仅解锁后显示）+ 上传中呼吸 ================= */
.chapter-gallery .gbox .gx {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 22px;
  height: 22px;
  display: none;
  align-items: center;
  justify-content: center;
  color: #f2ecff;
  font-size: 12px;
  line-height: 1;
  background: rgba(24, 16, 40, .78);
  border: 1px solid rgba(190, 160, 240, .5);
  border-radius: 50%;
  z-index: 4;
  pointer-events: auto;
}
.chapter-gallery.unlocked .gbox .gx { display: flex; }
.chapter-gallery.unlocked .gbox { cursor: pointer; }
.chapter-gallery .gbox.uploading::after {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(190, 160, 240, .18);
  animation: galUp 1.1s ease-in-out infinite;
  pointer-events: none;
  z-index: 3;
}
@keyframes galUp {
  0%, 100% { opacity: .25; }
  50% { opacity: .8; }
}
/* 锁死的格子：解锁态也不显示 ✕、不给手型光标 */
.chapter-gallery.unlocked .gbox.locked .gx { display: none; }
.chapter-gallery.unlocked .gbox.locked { cursor: default; }
